import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function Login() {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: "", password: "", totp: "" });
  const [message, setMessage] = useState("");
  const [otpRequired, setOtpRequired] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    try {
      const payload = { email: form.email, password: form.password };
      if (otpRequired) payload.totp = form.totp;

      const res = await axios.post("http://localhost:4000/api/auth/login", payload);

      const { token, user } = res.data;

      // If student and OTP required, show OTP input
      if (user.role === "student" && !otpRequired && !user.totpVerified) {
        setOtpRequired(true);
        setMessage("Enter the 6-digit OTP from your authenticator app");
        return;
      }

      // Save token and user to localStorage or context
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(user));

      // Redirect based on role
      if (user.role === "admin") navigate("/admin-dashboard");
      else if (user.role === "comelec") navigate("/comelec-dashboard");
      else navigate("/student-dashboard"); // for students
    } catch (err) {
      setMessage(err.response?.data?.error || "Login failed");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Login</h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          <input type="email" name="email" placeholder="Email" value={form.email} onChange={handleChange} required style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }} />
          <input type="password" name="password" placeholder="Password" value={form.password} onChange={handleChange} required style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }} />

          {otpRequired && (
            <input
              type="text"
              name="totp"
              placeholder="Enter OTP"
              value={form.totp}
              onChange={handleChange}
              required
              style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
            />
          )}

          <button type="submit" style={{ padding: "12px", borderRadius: "5px", border: "none", backgroundColor: "#007bff", color: "#fff", fontWeight: "bold", cursor: "pointer" }}>
            {otpRequired ? "Verify OTP" : "Login"}
          </button>
        </form>

        {message && <p style={{ marginTop: "20px", textAlign: "center", color: otpRequired ? "green" : "red" }}>{message}</p>}

        <p style={{ marginTop: "20px", textAlign: "center", color: "#555" }}>
          Don't have an account?{" "}
          <button
            type="button"
            style={{ color: "#007bff", fontWeight: "bold", cursor: "pointer", background: "none", border: "none", padding: 0 }}
            onClick={() => navigate("/register")}
          >
            Register
          </button>
        </p>
      </div>
    </div>
  );
}
